//! Initial original bytes shared by old and recorded-native producers.
pub const CASES:&[&str]=&["cross_file","related_boundaries","allow_order","excluded_schema"];
pub fn files(case:&str)->Option<Vec<(String,Vec<u8>)>>{let mut out=vec![("deepquarry.dme".into(),b"// raw ownership-form policy\n".to_vec()),("tools/ci/lint_scopes.toml".into(),if case=="excluded_schema"{b"[lint.\"sys/dx_ownership_forms\"]\nexempt_prefixes = [\"code/exempt/\"]\n".to_vec()}else{b"[lint.\"sys/dx_ownership_forms\"]\n".to_vec()})];let mut add=|relative:&str,text:&str|out.push((relative.into(),text.as_bytes().to_vec()));match case{
"cross_file"=>{add("code/cap.dm","/obj/shared/capabilities()\n\t. += cap_slot(nameof(contents))\n");add("maps/type.dm","/obj/shared/ownership()\n\t. += owns(nameof(contents))\nOWN(/obj/shared, contents)\nDESTROY_STEP(contents)\nown_set(src, \"contents\", null)\n");},
"related_boundaries"=>{add("code/cap.dm","/obj/root/capabilities()\n\t. += cap_slot(nameof(items))\n/obj/other/capabilities()\n\t. += cap_cell_holder(nameof(cell))\n");add("code/type.dm","/obj/root/child/ownership()\n\t. += owns(nameof(items))\n/obj/roots/ownership()\n\t. += owns(nameof(items))\n/obj/other/ownership()\n\t. += owns(nameof(cell))\n");},
"allow_order"=>{add("code/a.dm","/obj/root/capabilities()\n\t. += cap_slot(nameof(items))\nOWN(/obj/root, items) // ALLOW(sys_old_ownership_macro/FIRST): the compatibility adapter retains this exact original declaration\n");add("code/b.dm","/obj/root/ownership()\n\t. += owns(nameof(items)) // ALLOW(sys_owned_twice/SECOND): the compatibility adapter retains this ownership declaration\nDESTROY_AFTER(items)\n");},
"excluded_schema"=>{add("code/exempt/cap.dm","/obj/root/capabilities()\n\t. += cap_slot(nameof(items))\n");add("code/type.dm","/obj/root/ownership()\n\t. += owns(nameof(items))\nOWN(/obj/root, items)\n");},_=>return None}Some(out)}
